			function fn_egov_downFile(atchFileId, fileSn){
				window.open("/portal/cmm/fms/FileDown.do;jsessionid=AEE195C5FBD648C179792D1E3B4095FB?atchFileId="+atchFileId+"&fileSn="+fileSn+"");
			}

			function fn_egov_deleteFile(atchFileId, fileSn) {
				var orignlFileNm = document.getElementById("securitynttidheader").value; //id값 게시글 주인 로그인 정보 확인용//
				var streFileNm = document.getElementById("securitybbsidheader").value; //id값 게시글 주인 로그인 정보 확인용//
				if (confirm('삭제하시겠습니까?')) {
					$.ajax({
						url: '/portal/cmm/fms/deleteFileInfs.do;jsessionid=AEE195C5FBD648C179792D1E3B4095FB',
						type: 'post',
						data: {"atchFileId":atchFileId, "fileSn":fileSn, "orignlFileNm":orignlFileNm, "streFileNm":streFileNm},
						dataType: 'json',
						success: function(data) {
							 if (data.result === 'SUCCESS') {
								 	alert('정상적으로 삭제되었습니다.');
									fnSearchFile(atchFileId);
						        } else if (data.result === 'FAIL') {
						        	alert('실패하였습니다.');
						        }
							
						},
						error:function(request,status,error){
							//alert("code:"+request.status+"\n"+"error:"+error);
							alert("데이터를 불러오는데 실패했습니다.");
						}
					});
				}
			}

			function fn_egov_check_file(flag) {
				if (flag=="Y") {
					document.getElementById('file_upload_posbl').style.display = "";
					document.getElementById('file_upload_imposbl').style.display = "none";
				} else {
					document.getElementById('file_upload_posbl').style.display = "none";
					document.getElementById('file_upload_imposbl').style.display = "";
				}
			}
