			function fn_main_headPageMove(menuNo, url){
				document.selectOne.menuNo.value=menuNo;
				document.selectOne.link.value=url;
				document.selectOne.action = "/portal/PageLink.do;jsessionid=AEE195C5FBD648C179792D1E3B4095FB";
				//alert(document.selectOne.action);
				document.selectOne.submit();
			}

			function fn_main_headPageAction(menuNo, url){
				document.selectOne.menuNo.value=menuNo;
				document.selectOne.link.value="";
				document.selectOne.action = "/portal/;jsessionid=AEE195C5FBD648C179792D1E3B4095FB"+url;
				document.selectOne.method = "post";
				//alert(document.selectOne.action);
				document.selectOne.submit();
			}

$(document).ready(function(){

	var totalRecordCount = 38;
	var pageSize = 10;
	var pageIndex = 1;


	var totalPageCount = Math.ceil(totalRecordCount/pageSize);	
	var boardInfo = "총 게시물 <strong>"+totalRecordCount+"</strong>개, 페이지 <strong>"+pageIndex+"</strong> /"+totalPageCount;
	$("#pageInfo").html(boardInfo);
	var params = {
		divId : "paging_div",
		pageIndex : "pageIndex",
		cpageindex : pageIndex,
		recordCount : pageSize,
		totalCount : totalRecordCount,
		eventName : "fn_egov_select_linkPage"
	};	


	fn_renderPaging(params); 

	fn_egov_init();

});



